import { randomUUID } from "node:crypto";
import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";

// Private patient photos on the server's disk, inside PRIVATE_STORAGE_DIR.
// Never served publicly. No database, no external API: files only.

if (typeof window !== "undefined") {
  throw new Error("server/storage must never be imported in the browser.");
}

const ANALYSIS_FOLDER = "analyses";
const JPEG_MIME_TYPE = "image/jpeg";
const MAX_IMAGE_BYTES = 2 * 1024 * 1024; // 2 MB, same limit as Face++

// Only keys generated by savePrivateImage are accepted: "analyses/<uuid>.jpg".
const STORAGE_KEY_PATTERN =
  /^analyses\/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}\.jpg$/;

export type StorageErrorKind = "invalid_image" | "image_too_large" | "invalid_key";

export class StorageError extends Error {
  readonly kind: StorageErrorKind;

  constructor(kind: StorageErrorKind, message: string) {
    super(message);
    this.name = "StorageError";
    this.kind = kind;
  }
}

export type SavedPrivateImage = {
  storageKey: string;
  mimeType: string;
  size: number;
};

export type PrivateImageFile = SavedPrivateImage & {
  data: Buffer;
};

export async function savePrivateImage(file: Blob): Promise<SavedPrivateImage> {
  if (file.size === 0) {
    throw new StorageError("invalid_image", "The photo is empty.");
  }
  if (file.size > MAX_IMAGE_BYTES) {
    throw new StorageError("image_too_large", "The photo must be 2 MB or less.");
  }
  if (file.type !== JPEG_MIME_TYPE) {
    throw new StorageError("invalid_image", "Only JPEG photos are accepted.");
  }

  const data = Buffer.from(await file.arrayBuffer());

  // The declared type comes from the browser and can lie: check the JPEG signature too.
  if (!isJpeg(data)) {
    throw new StorageError("invalid_image", "Only JPEG photos are accepted.");
  }

  // The key is generated here; the original file name is never used.
  const storageKey = `${ANALYSIS_FOLDER}/${randomUUID()}.jpg`;
  const filePath = resolveStoragePath(storageKey);

  await mkdir(path.dirname(filePath), { recursive: true });
  // "wx": fail instead of overwriting if the file already exists.
  await writeFile(filePath, data, { flag: "wx" });

  return { storageKey, mimeType: JPEG_MIME_TYPE, size: data.length };
}

// Returns null when no file exists for this key.
export async function readPrivateImage(storageKey: string): Promise<PrivateImageFile | null> {
  const filePath = resolveStoragePath(storageKey);

  try {
    const data = await readFile(filePath);
    return { storageKey, mimeType: JPEG_MIME_TYPE, size: data.length, data };
  } catch (error) {
    if (isFileNotFound(error)) return null;
    throw error;
  }
}

// Deleting a file that is already gone is not an error.
export async function deletePrivateImage(storageKey: string): Promise<void> {
  const filePath = resolveStoragePath(storageKey);
  await rm(filePath, { force: true });
}

function getStorageRoot(): string {
  return path.resolve(process.cwd(), process.env.PRIVATE_STORAGE_DIR || "./private-storage");
}

// Turns a storage key into an absolute path, refusing anything that could leave the storage root.
function resolveStoragePath(storageKey: string): string {
  if (!STORAGE_KEY_PATTERN.test(storageKey)) {
    throw new StorageError("invalid_key", "Invalid storage key.");
  }

  const root = getStorageRoot();
  const filePath = path.resolve(root, storageKey);

  // Second barrier against path traversal, in case the pattern is ever loosened.
  if (!filePath.startsWith(root + path.sep)) {
    throw new StorageError("invalid_key", "Invalid storage key.");
  }
  return filePath;
}

// Every JPEG file starts with the bytes FF D8 FF.
function isJpeg(data: Buffer): boolean {
  return data.length >= 3 && data[0] === 0xff && data[1] === 0xd8 && data[2] === 0xff;
}

function isFileNotFound(error: unknown): boolean {
  return error instanceof Error && "code" in error && error.code === "ENOENT";
}
